package org.jlinalg.cli;

import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;
import htsjdk.samtools.util.BlockCompressedOutputStream;
import htsjdk.tribble.Feature;
import htsjdk.tribble.index.tabix.*;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;
import static org.junit.jupiter.api.Assertions.*;
import static org.jlinalg.cli.SeuratDifferentialContracts.*;

class CaddToolsTest {
    @TempDir Path temporary;
    private int run(String...args){return CaddToolsCli.run(args,new PrintStream(new ByteArrayOutputStream()),new PrintStream(new ByteArrayOutputStream()));}
    private int execute(Map<String,Object> r)throws IOException{Path p=temporary.resolve("request.json");json(p,r);return run("--request",p.toString());}
    private Map<String,Object> calibration()throws IOException{Files.writeString(temporary.resolve("table.txt"),"99\t20\n10\t1\n0\t-10\n");Files.writeString(temporary.resolve("raw.tsv"),"id\traw_score\nα literal\t1.1\nα literal\t-0.0\nnan-id\tNaN\n");var r=new LinkedHashMap<String,Object>();r.putAll(Map.of("schema_version",1,"mode","CALIBRATE","out","result","assembly","GRCh38","cadd_version","1.6","input_scores","raw.tsv","conversion_table","table.txt","conversion_sha256",CaddToolsFiles.pin(temporary.resolve("table.txt"),1000).get("sha256")));return r;}
    private record Point(String getContig,int getStart,int getEnd)implements Feature{ }
    private Map<String,Object> scoreTable(String id,String... rows)throws IOException{Path file=temporary.resolve(id+".tsv.gz");var index=new TabixIndexCreator(new TabixFormat(0,1,2,2,'#',0));htsjdk.tribble.index.Index complete;
        try(var out=new BlockCompressedOutputStream(file.toFile())){out.write("##CADD GRCh38-v1.6 SYNTHETIC_TEST_DATA_NOT_ORIGINAL_SCORES\n#Chrom\tPos\tRef\tAlt\tRawScore\tPHRED\n".getBytes(StandardCharsets.UTF_8));for(String row:rows){String[] f=row.split("\t");int pos=Integer.parseInt(f[1]);index.addFeature(new Point(f[0],pos,pos),out.getFilePointer());out.write((row+"\n").getBytes(StandardCharsets.UTF_8));}complete=index.finalizeIndex(out.getFilePointer());}Path tbi=temporary.resolve(id+".tsv.gz.tbi");complete.write(tbi);return Map.of("id",id,"file",file.toString(),"index",tbi.toString(),"sha256",CaddToolsFiles.pin(file,100000).get("sha256"),"index_sha256",CaddToolsFiles.pin(tbi,100000).get("sha256"));}
    private Map<String,Object> lookup()throws IOException{Files.writeString(temporary.resolve("input.vcf"),"##fileformat=VCFv4.2\n#CHROM\tPOS\tID\tREF\tALT\tQUAL\tFILTER\tINFO\tFORMAT\tα sample\n1\t10\tliteral-id\tA\tC,G\t.\tPASS\tX=NaN\tGT\t1|2\nchr1\t10\tother\tA\tC\t.\t.\t.\tGT\t0/1\n");var first=scoreTable("first","1\t10\tA\tC\t0.1000\t4.00","1\t10\tA\tC\t0.2000\t5.00");var second=scoreTable("second","1\t10\tA\tC\t9\t99","1\t10\tA\tG\t0.3000\t6.00");return new LinkedHashMap<>(Map.of("schema_version",1,"mode","LOOKUP","out","result","assembly","GRCh38","cadd_version","1.6","input_vcf","input.vcf","representation","literal","score_tables",List.of(first,second)));}
    @Test void calibrationRetainsDuplicateLiteralIdsAndPortableSavedVerification()throws Exception{assertEquals(0,execute(calibration()));Path root=temporary.resolve("result");String text=Files.readString(root.resolve("results/calibrated.tsv"));assertTrue(text.contains("α literal\t1.1\t1.100000\t99"));assertTrue(text.contains("α literal\t-0.0\t-0.000000\t10"));assertTrue(text.contains("NaN\tnan\tNA\tNONFINITE_RAW_UNASSESSABLE"));Files.delete(temporary.resolve("raw.tsv"));Files.delete(temporary.resolve("table.txt"));assertEquals(0,run("--verify",root.toString()));}
    @Test void allDuplicateSourceHitsAndExplicitPriorityAreRetained()throws Exception{var r=lookup();assertEquals(0,execute(r));Path root=temporary.resolve("result");var summary=read(root.resolve("result-summary.json"));assertEquals(3,((Number)summary.get("score_hits")).intValue());assertEquals(1,((Number)summary.get("no_score_alleles")).intValue());String scores=Files.readString(root.resolve("results/scores.tsv"));assertTrue(scores.contains("0.1000\t4.00"));assertTrue(scores.contains("0.2000\t5.00"));assertFalse(scores.contains("\t9\t99"));assertArrayEquals(Files.readAllBytes(temporary.resolve("input.vcf")),Files.readAllBytes(root.resolve("inputs/original.vcf")));assertTrue(Files.readString(root.resolve("results/alleles.tsv")).contains("NO_SCORE_DEPENDENT_PREDICTION_SKIPPED"));for(Object value:list(r.get("score_tables"),"tables")){var t=object(value,"table");Files.delete(Path.of(text(t,"file")));Files.delete(Path.of(text(t,"index")));}assertEquals(0,run("--verify",root.toString()));}
    @Test void derivedTamperCannotBeAdmittedByResealing()throws Exception{assertEquals(0,execute(calibration()));Path root=temporary.resolve("result");Path result=root.resolve("results/calibrated.tsv");Files.writeString(result,Files.readString(result).replace("\t99\t","\t98\t"));CaddToolsFiles.seal(root);assertEquals(2,run("--verify",root.toString()));}
    @Test void capturedQueryIdentityCannotBeResealedAsAnotherAllele()throws Exception{assertEquals(0,execute(lookup()));Path root=temporary.resolve("result");Path capture=root.resolve("lookup-capture.jsonl");Files.writeString(capture,Files.readString(capture).replace("\"position\":\"10\"","\"position\":\"11\""));CaddToolsFiles.seal(root);assertEquals(2,run("--verify",root.toString()));}
    @Test void extraResultOrChangedProducerCannotBeResealed()throws Exception{assertEquals(0,execute(calibration()));Path root=temporary.resolve("result");Files.writeString(root.resolve("results/extra"),"extra");CaddToolsFiles.seal(root);assertEquals(2,run("--verify",root.toString()));Files.delete(root.resolve("results/extra"));json(root.resolve("source-bindings.json"),Map.of());CaddToolsFiles.seal(root);assertEquals(2,run("--verify",root.toString()));}
    @Test void missingInputProducesSkipWithCauseAndConcreteAction()throws Exception{var r=calibration();r.put("input_scores","missing.tsv");assertEquals(3,execute(r));String warning=Files.readString(temporary.resolve("result/WARNINGS.md"));assertTrue(warning.contains("SKIP3"));assertTrue(warning.contains("missing.tsv"));assertTrue(warning.contains("REQUIRED ACTION"));assertEquals(2,run("--verify",temporary.resolve("result").toString()));}
    @Test void wrongHashIsFailureAndNeverAnEmptySuccess()throws Exception{var r=calibration();r.put("conversion_sha256","0".repeat(64));assertEquals(2,execute(r));assertEquals(false,read(temporary.resolve("result/analysis-status.json")).get("results_admitted"));}
    @Test void unknownUnusedAndEditionSubstitutionAreRefused()throws Exception{var r=calibration();r.put("threads",2);assertThrows(IOException.class,()->CaddToolsRequest.validate(r));r.remove("threads");r.put("input_vcf","unused.vcf");assertThrows(IOException.class,()->CaddToolsRequest.validate(r));r.remove("input_vcf");r.put("cadd_version","1.7");assertEquals(3,execute(r));}
    @Test void completeInputOutputAndRowCapacitiesDoNotTruncateToSuccess()throws Exception{var r=calibration();r.put("maximum_variants",1);assertEquals(2,execute(r));r.put("out","result2");r.put("maximum_variants",100);r.put("maximum_output_bytes",10);assertEquals(2,execute(r));r.put("out","result3");r.put("maximum_output_bytes",10000);r.put("maximum_input_bytes",5);assertEquals(2,execute(r));}
    @Test void existingOutputAndUniqueBytesArePreserved()throws Exception{var r=calibration();Files.createDirectory(temporary.resolve("result"));Files.writeString(temporary.resolve("result/unique"),"keep");assertEquals(2,execute(r));assertEquals("keep",Files.readString(temporary.resolve("result/unique")));}
}
